  const allElements = document.querySelectorAll('[data-*]');
  allElements.forEach(el => {
    data[el.id || el.className] = Object.fromEntries(
      Object.entries(el.dataset)
    );
  });

  // Check for any elements containing ID-like text
  const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );

  const textNodes = [];
  let node;
  while (node = walker.nextNode()) {
    if (/[a-z0-9]{8,}/.test(node.textContent)) {
      textNodes.push(node.textContent.trim());
    }
  }

  return {
    dataAttributes: data,
    textContent: textNodes,
    windowData: typeof window.orderData !== 'undefined' ? window.orderData : null
  };
});

